
create table if not exists agencies (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  category text not null,
  fb_url text unique,
  website text,
  phone_public text,
  description text,
  services text[] default '{}',
  followers int,
  logo_url text,
  last_post_at date,
  verified boolean not null default false,
  verified_at timestamptz,
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  added_by text not null default 'user' check (added_by in ('import','user','owner')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create table if not exists claims (
  id uuid primary key default gen_random_uuid(),
  agency_id uuid references agencies(id) on delete cascade,
  phone text not null,
  wesend_id text,
  status text not null default 'pending',
  created_at timestamptz not null default now()
);
create table if not exists reports (
  id uuid primary key default gen_random_uuid(),
  agency_id uuid references agencies(id) on delete cascade,
  message text not null,
  created_at timestamptz not null default now()
);
alter table agencies enable row level security;
alter table claims enable row level security;
alter table reports enable row level security;
drop policy if exists "public read approved" on agencies;
create policy "public read approved" on agencies for select using (status = 'approved');
drop policy if exists "anyone can report" on reports;
create policy "anyone can report" on reports for insert with check (char_length(message) between 3 and 1000);
create index if not exists agencies_cat on agencies(category);

on conflict (slug) do nothing;